use crate::state::GameState;use crate::ui::Tui;use std::io;
#[derive(Debug,Clone,PartialEq,Eq)]pub struct Achievement{pub id:&'static str,pub title:&'static str,pub description:&'static str,pub reward_title:Option<&'static str>,pub reward_theme:Option<&'static str>}
pub fn all_achievements()->Vec<Achievement>{vec![
Achievement{id:"first_blood",title:"First Blood",description:"Defeat your first monster.",reward_title:Some("Novice Slayer"),reward_theme:None},
Achievement{id:"lacoyx_slayer",title:"Vanquisher of Lacoyx",description:"Defeat War Commander Lacoyx.",reward_title:Some("Realm Hero"),reward_theme:Some("Infernal Red")},
Achievement{id:"master_artisan",title:"Master Artisan",description:"Reach level 100 in any skill.",reward_title:Some("Grandmaster"),reward_theme:Some("Golden Realm")},
Achievement{id:"gauntlet_10",title:"Gauntlet Conqueror",description:"Clear wave 10 in the Endless Gauntlet.",reward_title:Some("Gauntlet Legend"),reward_theme:Some("Obsidian Shadow")},
Achievement{id:"total_skill_300",title:"Well-Rounded Adventurer",description:"Reach total skill level 300.",reward_title:Some("Well-Rounded"),reward_theme:None}]}
fn met(s:&GameState,id:&str)->bool{let lv=[s.player.skills.woodcutting.level,s.player.skills.cooking.level,s.player.skills.fishing.level,s.player.skills.mining.level,s.player.skills.smithing.level,s.player.skills.thieving.level];match id{
"first_blood"=>s.player.lifetime_kills>0,"lacoyx_slayer"=>s.lacoyx_defeated,"master_artisan"=>lv.iter().any(|n|*n>=crate::data::MAX_SKILL_LEVEL),"gauntlet_10"=>s.stronghold_high_score>=10,"total_skill_300"=>s.player.skills.total_level()>=300,_=>false}}
pub fn evaluate_achievements(s:&mut GameState)->Vec<Achievement>{let mut got=Vec::new();for a in all_achievements(){if s.unlocked_achievements.iter().any(|id|id==a.id)||!met(s,a.id){continue}s.unlocked_achievements.push(a.id.into());if let Some(t)=a.reward_title{if !s.unlocked_titles.iter().any(|x|x==t){s.unlocked_titles.push(t.into())}}if let Some(t)=a.reward_theme{if !s.unlocked_themes.iter().any(|x|x==t){s.unlocked_themes.push(t.into())}}got.push(a)}got}
fn view(tui:&mut Tui,s:&GameState)->io::Result<()>{let msg=all_achievements().iter().map(|a|format!("{} {}\n{}\nReward: {}{}",if s.unlocked_achievements.iter().any(|x|x==a.id){"[Unlocked]"}else{"[Locked]"},a.title,a.description,a.reward_title.unwrap_or("None"),a.reward_theme.map(|t|format!(" · Theme: {t}")).unwrap_or_default())).collect::<Vec<_>>().join("\n\n");tui.show_text("Achievements",&msg,Some(s))}
fn theme(tui:&mut Tui,s:&mut GameState)->io::Result<()>{let themes=s.unlocked_themes.clone();let mut o=themes.clone();o.push("Back".into());let r:Vec<&str>=o.iter().map(String::as_str).collect();let i=tui.select_menu(&format!("Terminal Theme · active: {}",s.active_theme),&r,Some(s))?;if i<themes.len(){s.active_theme=themes[i].clone();tui.show_message("Theme changed",&format!("Theme set to {}.",s.active_theme),Some(s))?}Ok(())}
fn title(tui:&mut Tui,s:&mut GameState)->io::Result<()>{if s.unlocked_titles.is_empty(){tui.show_message("Hero Titles","No titles unlocked yet.",Some(s))?;return Ok(())}let t=s.unlocked_titles.clone();let mut o=t.clone();o.push("Clear active title".into());o.push("Back".into());let r:Vec<&str>=o.iter().map(String::as_str).collect();let i=tui.select_menu("Hero Title",&r,Some(s))?;if i<t.len(){s.active_title=Some(t[i].clone())}else if i==t.len(){s.active_title=None}Ok(())}
pub fn progression_menu(tui:&mut Tui,s:&mut GameState)->io::Result<()>{loop{match tui.select_menu("Progression & Customization",&["Mastery Perks","View Achievements","Select Terminal Theme","Select Hero Title","Back"],Some(s))?{0=>crate::mastery::mastery_menu(tui,s)?,1=>view(tui,s)?,2=>theme(tui,s)?,3=>title(tui,s)?,_=>return Ok(())}}}
#[cfg(test)]mod tests{use super::*;use crate::state::Player;fn state()->GameState{GameState::new(Player::new("Hero".into(),String::new()))}
#[test]fn achievement_unlocks_are_idempotent(){let mut s=state();s.player.lifetime_kills=1;s.lacoyx_defeated=true;let a=evaluate_achievements(&mut s);assert!(a.iter().any(|x|x.id=="first_blood"));assert!(s.unlocked_titles.contains(&"Novice Slayer".to_string()));assert!(s.unlocked_themes.contains(&"Infernal Red".to_string()));assert!(evaluate_achievements(&mut s).is_empty());}
#[test]fn gauntlet_score_unlocks_theme(){let mut s=state();s.stronghold_high_score=10;let a=evaluate_achievements(&mut s);assert!(a.iter().any(|x|x.id=="gauntlet_10"));assert!(s.unlocked_themes.contains(&"Obsidian Shadow".to_string()));}
}